using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 FlowLayoutPanel footingSettings;ComboBox footingFc,footingSmall,footingLarge;readonly List<CheckedListBox> stockChecks=new List<CheckedListBox>();bool refreshingStocks;
 void AddWorksSettings(){
  foreach(var form in new Form[]{beam,slab})foreach(var tools in form.Controls.OfType<FlowLayoutPanel>())foreach(var button in tools.Controls.OfType<Button>().Where(b=>b.Text=="Settings").ToArray())button.Visible=false;
  footingSettings=new FlowLayoutPanel{Visible=false,AutoScroll=true,Padding=new Padding(12)};Controls.Add(footingSettings);
  footingFc=SettingChoice(footingSettings,"Concrete strength MPa",new[]{"21","28","35"});footingSmall=SettingChoice(footingSettings,"Rebar <=12 mm grade",new[]{"40","60"});footingLarge=SettingChoice(footingSettings,"Rebar >=16 mm grade",new[]{"60","40"});
  Button(footingSettings,"Apply to all footings",()=>{Commit();filling=true;try{foreach(DataGridViewRow row in footings.Rows)if(!row.IsNewRow){row.Cells[25].Value=footingFc.Text;row.Cells[26].Value=footingSmall.Text;row.Cells[27].Value=footingLarge.Text;}}finally{filling=false;}Recalculate();});
  footingSettings.Controls.Add(new Label{Text="Selections are defaults for new footings. Apply to all footings updates existing rows. Saved projects keep their individual materials until you apply changes.",Width=780,Height=60,Padding=new Padding(6)});
  footings.DefaultValuesNeeded+=(s,e)=>SetFootingMaterials(e.Row);footings.RowsAdded+=(s,e)=>{if(!filling)for(int i=e.RowIndex;i<e.RowIndex+e.RowCount;i++)if(!footings.Rows[i].IsNewRow)SetFootingMaterials(footings.Rows[i]);};
  for(int c=25;c<=27;c++)footings.Columns[c].Visible=false;
  var page=new TabPage("Reinforced Concrete Start");var start=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(20)};page.Controls.Add(start);tabs.TabPages.Add(page);start.Controls.Add(new Label{Text="REINFORCED CONCRETE WORKS | SETTINGS",Width=1100,Height=52,Font=new Font("Segoe UI",19,FontStyle.Bold),ForeColor=PowTheme.Ink});start.Controls.Add(new Label{Text="Set beam, slab and foundation materials and available rebar lengths before estimating.",Width=1100,Height=42,ForeColor=PowTheme.Muted});
  var card=new PowCard{Width=1120,Height=326};var heading=new Label{Text="BEAM, SLAB & FOUNDATION SETTINGS",Left=16,Top=12,Width=900,Height=26,Font=new Font("Segoe UI",11,FontStyle.Bold)};card.Controls.Add(heading);
  var actions=new FlowLayoutPanel{Left=12,Top=42,Width=1050,Height=42};Button(actions,"Beam Settings",()=>ShowMemberSettings(0));Button(actions,"Slab Settings",()=>ShowMemberSettings(1));Button(actions,"Foundation / Footing Settings",()=>ShowMemberSettings(2));AddCanopySettings(actions);var doorTools=tabs.TabPages.Cast<TabPage>().Single(p=>p.Text=="Wooden Doors & Windows").Controls.OfType<FlowLayoutPanel>().Single();AddDoorSettings(doorTools);card.Controls.Add(actions);
  string[] names={"Beam","Slab","Foundation / Footing"};for(int n=0;n<3;n++){int index=n;var label=new Label{Text=names[n]+" stock lengths (m)",Left=18+n*350,Top=90,Width=320,Height=24};var list=new CheckedListBox{Left=18+n*350,Top=116,Width=320,Height=155,CheckOnClick=true,MultiColumn=true,ColumnWidth=100};card.Controls.Add(label);card.Controls.Add(list);stockChecks.Add(list);list.ItemCheck+=(s,e)=>{if(refreshingStocks)return;var chosen=Enumerable.Range(0,list.Items.Count).Where(i=>i==e.Index?e.NewValue==CheckState.Checked:list.GetItemChecked(i)).Select(i=>(double)list.Items[i]).ToList();if(chosen.Count==0){e.NewValue=e.CurrentValue;return;}if(index==0)beam.SetWorksStockLengths(chosen);else if(index==1)slab.SetWorksStockLengths(chosen);else footingStock=chosen;Recalculate();};}
  card.Controls.Add(new Label{Text="Only checked lengths are used for cutting, purchase quantities and backup computation. Keep at least one length checked in each group.",Left=18,Top=278,Width=1060,Height=32,ForeColor=PowTheme.Muted});start.Controls.Add(card);Action resizeStart=()=>{int width=start.ClientSize.Width-start.Padding.Horizontal-22;if(width<500)return;foreach(Control child in start.Controls){child.Width=width;if(child==card)continue;var panel=child as Panel;if(panel!=null)foreach(Control inner in panel.Controls)if(inner.Width>width-40)inner.Width=width-40;}int column=(width-48)/3;for(int n=0;n<stockChecks.Count;n++){stockChecks[n].Left=18+n*(column+8);stockChecks[n].Width=column;var label=card.Controls.OfType<Label>().First(l=>l.Text==new[]{"Beam","Slab","Foundation / Footing"}[n]+" stock lengths (m)");label.Left=stockChecks[n].Left;label.Width=column;}foreach(var label in card.Controls.OfType<Label>().Where(l=>l.Width>width-36))label.Width=width-36;var actionsPanel=card.Controls.OfType<FlowLayoutPanel>().First();actionsPanel.Width=width-30;var stats=start.Controls.OfType<FlowLayoutPanel>().FirstOrDefault(p=>p.Controls.OfType<PowCard>().Count()==6);if(stats!=null){stats.Width=width;foreach(var metric in stats.Controls.OfType<PowCard>()){metric.Width=column;foreach(Control label in metric.Controls)label.Width=column-30;}}};start.Resize+=(s,e)=>resizeStart();Shown+=(s,e)=>resizeStart();resizeStart();RefreshStockChecks();start.VisibleChanged+=(s,e)=>{if(start.Visible)RefreshStockChecks();};
 }
 static ComboBox SettingChoice(FlowLayoutPanel panel,string name,string[] choices){var group=new FlowLayoutPanel{Width=240,Height=76,FlowDirection=FlowDirection.TopDown};group.Controls.Add(new Label{Text=name,Width=235,Height=26});var box=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=220};box.Items.AddRange(choices);box.SelectedIndex=0;group.Controls.Add(box);panel.Controls.Add(group);return box;}
 void SetFootingMaterials(DataGridViewRow row){row.Cells[25].Value=footingFc.Text;row.Cells[26].Value=footingSmall.Text;row.Cells[27].Value=footingLarge.Text;}
 void ShowMemberSettings(int member){Commit();var panels=new Control[]{beam.WorksSettings,slab.WorksSettings,footingSettings};var names=new[]{"Beam","Slab","Footing"};SettingsWorkspace.Show(this,names[member],new[]{names[member]+" settings"},new[]{panels[member]});Recalculate();RefreshStockChecks();}
 void ShowWorksSettings(){Commit();SettingsWorkspace.Show(this,"Program of Works",new[]{"Beam","Slab","Footing"},new Control[]{beam.WorksSettings,slab.WorksSettings,footingSettings});Recalculate();RefreshStockChecks();}
 void RefreshStockChecks(){if(stockChecks.Count!=3)return;refreshingStocks=true;try{var selected=new[]{beam.WorksStockLengths,slab.WorksStockLengths,footingStock};for(int n=0;n<3;n++){var list=stockChecks[n];list.Items.Clear();foreach(double length in CommercialBars.Lengths.Concat(selected[n]).Distinct().OrderBy(x=>x))list.Items.Add(length,selected[n].Contains(length));}}finally{refreshingStocks=false;}}
 void WriteMaterialDefaults(System.Xml.XmlElement root){WriteDoorSettings(root);WriteCanopySettings(root);root.SetAttribute("footingFcDefault",footingFc.Text);root.SetAttribute("footingSmallDefault",footingSmall.Text);root.SetAttribute("footingLargeDefault",footingLarge.Text);}
 void ReadMaterialDefaults(System.Xml.XmlElement root){ReadDoorSettings(root);ReadCanopySettings(root);foreach(var pair in new[]{new{Box=footingFc,Name="footingFcDefault"},new{Box=footingSmall,Name="footingSmallDefault"},new{Box=footingLarge,Name="footingLargeDefault"}})if(root.HasAttribute(pair.Name)){string value=root.GetAttribute(pair.Name);if(!pair.Box.Items.Contains(value))throw new Exception("Invalid footing material default.");pair.Box.SelectedItem=value;}}
}
}
